from app.ingestion import create_chunks
from app.config import CHUNK_SIZE
import pytest

def test_create_chunks_with_short_text():

    text = "That is a short text."
    origin = "test.pdf"
    chunks = create_chunks(text, origin) 

    assert len(chunks) > 0
    assert chunks[0].page_content == text
    assert chunks[0].metadata["source"] == origin

def test_create_chunks_with_long_text():

    text = """For centuries, art has been considered the ultimate frontier of the human soul. It is a deeply personal expression of our emotions, experiences, fears, and triumphs. From the raw charcoal drawings on cave walls to the complex symphonies of the Romantic era, creativity has served as a mirror to our consciousness. We assumed that while machines could automate labor, calculate complex formulas, and organize data, they would never grasp the chaotic, beautiful spark required to create something original. However, the rapid advancement of artificial intelligence has challenged this long-held assumption, forcing us to re-evaluate what it truly means to be creative. The emergence of generative AI models capable of producing stunning visual art, intricate musical compositions, and compelling literature has sparked a global debate. Critics argue that algorithms are merely mimicking human behavior, rearranging pixels and words based on statistical probabilities derived from vast datasets of existing human work. They contend that without genuine consciousness, suffering, or joy, a machine cannot produce true art. In this view, AI-generated content is a sophisticated form of plagiarism—a hollow imitation lacking the emotional resonance that defines masterpiece creations. Conversely, a growing community of technologists and forward-thinking artists view artificial intelligence not as a replacement, but as a revolutionary tool. Throughout history, new technologies have always disrupted the artistic landscape. The invention of photography in the 19th century initially terrified painters, who feared the absolute death of their medium. Instead, it liberated them from the burden of hyper-realistic representation, giving birth to Impressionism, Cubism, and modern abstract art. AI may very well represent a similar evolutionary leap, serving as a bicycle for the mind that amplifies human capability.
            When an artist collaborates with an AI, the creative process undergoes a profound shift. The human artist transitions from being the sole executor of a vision to acting as a curator, director, and conceptual architect. They provide the initial prompt—the thematic seed—and then guide, filter, and refine the outputs generated by the machine. This iterative loop can lead to unexpected digital mutations and serendipitous discoveries that a human mind might never have conceived on its own. In this context, creativity is no longer defined by technical execution alone, but by the depth of the questions asked and the choices made during curation.
            However, this technological shift introduces significant ethical and economic dilemmas that society must urgently address. The datasets used to train these massive models consist of millions of copyrighted works created by human artists, often scraped from the internet without consent, compensation, or credit. As AI systems become capable of generating commercial-grade artwork in seconds, traditional illustrators, writers, and musicians face unprecedented threats to their livelihoods. The legal frameworks governing intellectual property are struggling to keep pace, leaving a gray area where the line between inspiration and theft is heavily blurred.
            Looking toward the future, the relationship between humanity and machines will likely evolve into a complex symbiosis. We are moving into an era where the distinction between human-made and machine-made content will become increasingly difficult to discern. Yet, this saturation of automated content might paradoxically increase the value of the raw, flawed, and authentic human touch. Just as mass-produced furniture sparked a renewed appreciation for handcrafted woodwork, the rise of synthetic media may trigger a cultural renaissance that deeply values human vulnerability, live performances, and physical mediums.
            Ultimately, artificial intelligence is expanding the horizon of what is possible, challenging us to redefine the boundaries of imagination. It reminds us that creativity is not a finite resource to be guarded, but an ever-evolving conversation between the tools we build and the stories we want to tell. Whether AI is viewed as a threat to human uniqueness or the ultimate collaborator, it has undeniably opened a new chapter in the history of expression—one written in both ink and code."""
    origin = "test.pdf"
    chunks = create_chunks(text, origin)

    assert len(chunks) > 2
    assert chunks[0].page_content == "For centuries, art has been considered the ultimate frontier of the human soul. It is a deeply personal expression of our emotions, experiences, fears, and triumphs. From the raw charcoal drawings on cave walls to the complex symphonies of the Romantic era, creativity has served as a mirror to our consciousness. We assumed that while machines could automate labor, calculate complex formulas, and organize data, they would never grasp the chaotic, beautiful spark required to create something"
    
    for chunk in chunks:
        assert len(chunk.page_content) <= CHUNK_SIZE

def test_create_chunks_with_empty_text():
    with pytest.raises(ValueError):
        text = ""
        origin = "test.pdf"
        chunks = create_chunks(text, origin)
        assert chunks == []